/// Read-only diagnostic; exact input construction from decide().
pub fn diagnostic_inputs(&self, t: f64) -> LadderInputs {
    let r = self.cfg.rules;
    let mut live = [0.0, 0.0];
    for lane in 0..LANES {
        if let Some(id) = self.known[lane] {
            live[lane % 2] += self.orders[&id].open();
        }
    }
    let rung_cur = [2, 3].map(|lane| self.cur(lane).map(|id| (self.orders[&id].tick, self.orders[&id].size)));
    let x = LadderInputs {
        rel_s: (t - self.ws) / 1000.0,
        book: self.book,
        binance: if r.g1 || r.g2 { self.binance.state(t, r.g1, r.g2) } else { [false, false] },
        v: [self.v[0].value(t), self.v[1].value(t)],
        net: self.knet,
        live,
        rung_cur,
    };
    x
}
